--!strict
-- Detailed rank presentation is opened as an exclusive Lobby panel; ProfileUI owns the compact HUD.
local Players=game:GetService("Players");local ReplicatedStorage=game:GetService("ReplicatedStorage");local player=Players.LocalPlayer;local folder=ReplicatedStorage:WaitForChild("Remotes",10);if not folder then return end;local remote=folder:WaitForChild("RankUpdated")::RemoteEvent
local gui=Instance.new("ScreenGui");gui.Name="RankGui";gui.ResetOnSpawn=false;gui.IgnoreGuiInset=false;gui.Enabled=false;gui.Parent=player.PlayerGui;local panel=Instance.new("Frame");panel.AnchorPoint=Vector2.new(.5,.5);panel.Position=UDim2.fromScale(.5,.5);panel.Size=UDim2.fromScale(.34,.2);panel.BackgroundColor3=Color3.fromRGB(90,65,35);panel.Parent=gui;local label=Instance.new("TextLabel");label.Size=UDim2.fromScale(1,.62);label.BackgroundTransparency=1;label.TextColor3=Color3.new(1,1,1);label.TextScaled=true;label.Text="木桶村民 III・0 RP";label.Parent=panel;local close=Instance.new("TextButton");close.Position=UDim2.fromScale(.2,.7);close.Size=UDim2.fromScale(.6,.2);close.Text="關閉";close.TextScaled=true;close.Parent=panel;close.Activated:Connect(function()gui.Enabled=false end);local constraint=Instance.new("UISizeConstraint");constraint.MinSize=Vector2.new(260,100);constraint.MaxSize=Vector2.new(480,180);constraint.Parent=panel
remote.OnClientEvent:Connect(function(data)label.Text=string.format("%s・%d RP",data.newRank or data.displayName or"木桶村民 III",data.total or data.points or 0)end)
